params.content:
body {
    font-family: Arial, sans-serif;
    background-color: #f4f4f4;
    color: #333;
    margin: 0;
    padding: 0;
}

header {
    background-color: #007BFF;
    color: #fff;
    text-align: center;
    padding: 2rem 0;
}

header h1 {
    font-size: 2.5rem;
    margin: 0;
}

header p {
    font-size: 1.2rem;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1rem;
}

main {
    padding: 2rem 0;
}

.subscription {
    background-color: #fff;
    margin: 0 auto;
    max-width: 600px;
    padding: 2rem;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: bold;
}

.form-group input,
.form-group select {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

button {
    background-color: #007BFF;
    color: #fff;
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

button:hover {
    background-color: #0056b3;
}

footer {
    background-color: #333;
    color: #fff;
    text-align: center;
    padding: 1rem 0;
    margin-top: 2rem;
}

footer p {
    margin: 0;
}

document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('newsletterForm');

    form.addEventListener('submit', function(event) {
        event.preventDefault();

        const email = document.getElementById('email').value;
        const name = document.getElementById('name').value;
        const interests = Array.from(document.getElementById('interests').selectedOptions).map(option => option.value);

        // Simple validation
        if (!email || !name || interests.length === 0) {
            alert('Please fill in all fields and select at least one interest.');
            return;
        }

        // Simulate form submission
        alert(`Thank you, ${name}! You have subscribed to the newsletter with the email ${email} and interests: ${interests.join(', ')}`);

        // Clear form fields
        form.reset();
    });
});
